/**
 * Page titles.
 *
 * The (main) layout's title template appends " | NigerianDirectory.com", so
 * a page title must not carry the brand itself, or it appears twice.
 * Stored meta_title values were generated by the crawler with the brand
 * already appended and then cut at 60 characters, leaving fragments such
 * as "… | NigerianDire". Everything from the first " | " is dropped.
 */
export function pageTitle(stored: string | null | undefined, fallback: string): string {
  const base = (stored || '').split(' | ')[0].trim();
  return base || fallback;
}
